    "effectZh": "此卡的\n[Raid Trigger]\n在可发动 Raid 时，必须发动。\n【Raid】\n卡名为包含「Ouz」的角色 激活并移动至前线L\n在此角色造成的伤害进行的触发检查中，对方无法发动 [激活]。\n【登场时】\n选择对方的BP4000以下的位于前线L的角色最多1张，置于其牌库下方。\n若自己的生命值为2以上，则将自己生命区域中的卡1张置于自己的牌库下方。",
