    "feature": "ドクター",
    "generatedEnergy": "蓝色×3",
    "effect": "このキャラの下に裏向きのカードがあり、このキャラが相手の効果で退場する場合、代わりにこのキャラの下の裏向きのカードを1枚場外に置いてもよい。\n[登場時]\n必要エナジーが5以下でカード名に「エグゼイド」を含む自分の場の他のキャラを1枚選んでもよい。そうした場合、そのキャラとそのキャラの下の裏向きのカードを裏向きでこのキャラの下に置き、カードを1枚引き、相手のフロントLのキャラを1枚まで選び、次の自分のターン開始時まで、元々の効果を全て失わせる。",
    "effectZh": "若本角色下方有里向卡片且此角色因对方效果退场时，也可以代替将本角色下方的 1 张里向卡片置于场外。\n[登场时]\n若必要能量为 5 以下，可选择自己场上其他卡名包含「Ex-Aid」的角色至多 1 张。如此选择的情况下，将该角色及其下方的里向卡片以里向状态置于本角色下方，抽 1 张牌，最多将对方前线 L 的 1 张角色选择后，直到下一个自己的回合开始为止，使其失去原本的所有效果。",
    "trigger": "[ゲット]\nこのカードを手札に加える。",
    "triggerZh": "[获取]\n将此卡加入手札。",
    "officialUrl": "https://www.unionarena-tcg.com/jp/cardlist/detail.php?card_no=UA29BT%2FKMR-1-051",
    "variant": "普通版",
    "image": "/cards/kamen-rider-2/UA29BT_KMR-1-051.png"
