    "effectZh": "[Raid]\n使卡名包含「Ex-Aid」的角色激活，并可移动至前线 L。\n本角色的 BP+1000。\n根据本角色下方的里向卡片数量，此角色获得以下所有效果。\n・2 张以上：\n[攻击 2 次]\n・4 张以上：此角色不会因战斗败北或卡的效果离开场地，也不会受到减少 BP 的效果。\n[登场时]\n若本角色的 Raid 源为必要能量 5 以上的卡片，也可以从自己山札上方取 1 张以里向状态置于本角色下方。",
