    "nameZh": "假面骑士 Gav 大师模式",
    "series": "假面骑士",
    "color": "黄色",
    "type": "角色卡",
    "rarity": "SR",
    "cost": 5,
    "ap": 1,
    "bp": "4000+",
    "feature": "-",
    "generatedEnergy": "黄色×1",
    "effect": "[レイド]\nカード名に「ガヴ」を含むキャラ アクティブにし、フロントLに移動できる\nこのターン中にこのキャラが自分の効果で登場している場合、このキャラはBP+1000と\n[インパクト（1）]\nを得る。\nこのキャラのアタック終了時、自分がこのアタックフェイズでレイドしていない場合、「自分の手札の〈仮面ライダーガヴ オーバーモード〉を1枚公開し、自分の場の〈ゴチゾウ〉を1枚退場させる。」をしてもよい。そうした場合、レイド状態のこのキャラの一番上のカードを手札に戻し、公開したカードをこのキャラのレイド元のカードにレイドさせる。\n[登場時]\n[アタック時]\n自分の手札から〈ゴチゾウ〉を1枚まで自分のエナジーLにレストで登場させる。",
    "effectZh": "[雷德]\n名称包含「Gav」的角色处于激活状态并可移动至前线 L\n若本回合内此角色通过自身效果登场，则此角色获得 BP+1000 与\n[冲击（1）]\n当自己的角色的攻击结束时，如果自己在该攻击阶段未进行雷德，则可以“公开自己手牌中的一张〈假面骑士 Gav Over Mode〉并使己方场上的〈哥兹兽〉退场”。如此则将处于雷德状态的本角色最上方的卡返回手牌，并将公开的卡作为本角色的原雷德基卡再次雷德。\n[登场时]\n[攻击时]\n从自己手牌中最多将一张〈哥兹兽>横置登场至自己的能量线 L。",
    "trigger": "[レイド]\nこのカードを手札に加えるか、必要エナジーを満たしている場合、レイドさせる。",
    "triggerZh": "[雷德]\n将此卡加入手牌或满足必要能量条件时，进行雷德。",
    "officialUrl": "https://www.unionarena-tcg.com/jp/cardlist/detail.php?card_no=EX12BT%2FKMR-2-012",
    "variant": "异图",
    "image": "/cards/kamen-rider-3/EX12BT_KMR-2-012_p1.png"
