    "generatedEnergy": "蓝色×3",
    "effect": "[登場時]\n自分の場外から必要エナジーが0の〔フィールドカードかイベントカードかカード名に「オーズ」を含むキャラカード〕を2枚まで手札に加える。2枚手札に加えた場合、自分の手札を1枚場外に置く。\n[起動メイン]\n[ターン1]\n自分の手札の必要エナジーが同じカードを3枚場外に置く。そうした場合、自分の場のキャラを1枚まで選び、このターン中、BP+1000し、このメインフェイズ終了時、カードを3枚引く。",
    "effectZh": "[登场时]\n从自己场外中选择至多 2 张〔场地卡或事件卡或卡名为“OOO”的角色卡片］加入手札。将 2 张加入手札的情况下，将自己手札中 1 张置入场外。\n[启动主]\n[回合 1]\n将自己手札中必要能量相同的卡合计 3 张置入场外。如此做的话，选择自己场上的角色中的至多 1 张，在本回合中 BP+1000，并在本主阶段结束时抽 3 张牌。",
