    "effectZh": "[Raid]\n〈假面骑士 Decade〉被激活并可移动至前线 L\n[登场时]\n抽入 1 张卡，将手牌中的［特征：Re・Imagination］最多 2 张移至移除区。选择对手的前线 L 中 BP 总和不超过本效果置于移除区的卡的总 BP 的 1 张角色卡并将其退场。此角色在下一个自己回合开始之时起至该时刻止，获得由本效果置于移除区的卡所持有的所有\n[在自己回合期间]\n的效果与\n[在对手回合期间]\n的效果。",
    "trigger": "[レイド]\nこのカードを手札に加えるか、必要エナジーを満たしている場合、レイドさせる。",
    "triggerZh": "[Raid]\n若将此卡加入手牌或满足必要能量时，发动 Raid。",
