    "effect": "自分の場のキャラを1枚選び、このターン中、BP+2500と「このキャラがアタックしてバトルに勝利した時、カードを1枚引く。」を与える。選んだキャラがカード名に「龍騎」を含むキャラの場合、さらにこのターン中、\n[狙い撃ち]\n（相手のフロントLのキャラを指定してアタックでき、その場合ブロックされない）を与える。",
    "effectZh": "选择自己战线的 1 张角色卡，本回合中给予其「BP+2500」和「该角色攻击并赢得战斗时，抽 1 张牌。」。若选中的角色卡名包含“龙骑”，则进一步在本回合中给予\n[精准射击]\n（指定对方前线 L 的角色卡进行攻击且不会被阻挡）。",
